 page.locator('#devOrb').click();page.locator('#devLogout').click();assert page.locator('#travelMenu [data-travel]').count()==5;before=page.evaluate('window.__travel.position()');private=next(i['id'] for i in ids if i['id'].startswith('building-'));page.evaluate('(id)=>window.__travel.teleport(id)',private);assert page.evaluate('window.__travel.position()')==before;walk=page.evaluate('window.__travel.walkEntrance()');assert walk['samples']==82 and not walk['failures'],walk;page.locator('#travelMenu').evaluate('e=>e.open=false');page.evaluate('window.__travel.frontView()');page.wait_for_timeout(400);page.screenshot(path='/tmp/nknu-canteen-entrance-gap-filled.png');assert not errors,errors
